// Hard spend caps per run and per task. Synchronous, so reserve/commit/release are atomic under concurrency.

const EPS = 1e-9;

export class BudgetExceeded extends Error {
  constructor(message: string) {
    super(message);
    this.name = "BudgetExceeded";
  }
}

export interface Reservation {
  commit(actualUsd: number): void;
  release(): void;
}

function checkAmount(usd: number, what: string): void {
  if (!Number.isFinite(usd) || usd < 0) throw new RangeError(`${what} must be a finite number >= 0, got ${usd}`);
}

export class BudgetGuard {
  private usedUsd = 0;
  private reservedUsd = 0;
  private readonly taskTotals = new Map<string, number>(); // committed + reserved per task

  constructor(
    private readonly runCapUsd: number,
    private readonly taskCapUsd: number,
  ) {
    checkAmount(runCapUsd, "runCapUsd");
    checkAmount(taskCapUsd, "taskCapUsd");
  }

  reserve(task: string, usd: number): Reservation {
    checkAmount(usd, "reservation");
    if (this.reservedUsd + this.usedUsd + usd > this.runCapUsd + EPS) {
      throw new BudgetExceeded(`run cap $${this.runCapUsd} exceeded by reserving $${usd} for ${task}`);
    }
    const taskTotal = this.taskTotals.get(task) ?? 0;
    if (taskTotal + usd > this.taskCapUsd + EPS) {
      throw new BudgetExceeded(`task cap $${this.taskCapUsd} exceeded by reserving $${usd} for ${task}`);
    }
    this.reservedUsd += usd;
    this.taskTotals.set(task, taskTotal + usd);

    let settled = false;
    const settle = (action: string): void => {
      if (settled) throw new Error(`reservation for ${task} already settled; cannot ${action}`);
      settled = true;
      this.reservedUsd -= usd;
    };
    return {
      commit: (actualUsd: number): void => {
        checkAmount(actualUsd, "actualUsd");
        settle("commit");
        this.usedUsd += actualUsd;
        this.taskTotals.set(task, (this.taskTotals.get(task) ?? 0) - usd + actualUsd);
      },
      release: (): void => {
        settle("release");
        this.taskTotals.set(task, (this.taskTotals.get(task) ?? 0) - usd);
      },
    };
  }

  /** Committed spend so far. */
  used(): number {
    return this.usedUsd;
  }

  /** Run cap minus committed and reserved spend; may be negative if actuals overran. */
  remaining(): number {
    return this.runCapUsd - this.usedUsd - this.reservedUsd;
  }
}
