  /** Run cap minus committed and reserved spend; may be negative if actuals overran. */
  remaining(): number {
    return this.runCapUsd - this.usedUsd - this.reservedUsd;
  }
}

import { describe, expect, test } from "bun:test";
import { BudgetExceeded, BudgetGuard } from "../src/harness/budget";

describe("BudgetGuard", () => {
  test("reserve counts against remaining; commit replaces it with actual", () => {
    const g = new BudgetGuard(10, 5);
    const r = g.reserve("a", 3);
    expect(g.used()).toBe(0);
    expect(g.remaining()).toBe(7);
    r.commit(2);
    expect(g.used()).toBe(2);
    expect(g.remaining()).toBe(8);
  });

  test("release frees the reservation", () => {
    const g = new BudgetGuard(10, 5);
    g.reserve("a", 4).release();
    expect(g.remaining()).toBe(10);
    g.reserve("a", 5).release();
  });

  test("run cap includes reserved and used", () => {
    const g = new BudgetGuard(10, 10);
    g.reserve("a", 6).commit(6);
    g.reserve("b", 3);
    expect(() => g.reserve("c", 1.5)).toThrow(BudgetExceeded);
    g.reserve("c", 1);
  });

  test("task cap applies per task across reservations and commits", () => {
    const g = new BudgetGuard(100, 5);
    g.reserve("a", 3).commit(3);
    expect(() => g.reserve("a", 2.5)).toThrow(BudgetExceeded);
    g.reserve("a", 2);
    g.reserve("b", 5);
  });

  test("actual may exceed reservation and still counts", () => {
    const g = new BudgetGuard(10, 5);
    g.reserve("a", 1).commit(4);
    expect(g.used()).toBe(4);
    expect(() => g.reserve("a", 1.5)).toThrow(BudgetExceeded);
    expect(g.remaining()).toBe(6);
  });

  test("double commit/release throws", () => {
    const g = new BudgetGuard(10, 5);
    const a = g.reserve("a", 1);
    a.commit(1);
    expect(() => a.commit(1)).toThrow();
    expect(() => a.release()).toThrow();
    const b = g.reserve("a", 1);
    b.release();
    expect(() => b.release()).toThrow();
    expect(() => b.commit(1)).toThrow();
    expect(g.used()).toBe(1);
    expect(g.remaining()).toBe(9);
  });

  test("concurrent reservations never exceed the cap", async () => {
    const g = new BudgetGuard(10, 10);
    let ok = 0;
    await Promise.all(
      Array.from({ length: 50 }, async (_, i) => {
        await Promise.resolve();
        try {
          const r = g.reserve(`t${i}`, 1);
          ok++;
          await Promise.resolve();
          r.commit(1);
        } catch (e) {
          expect(e).toBeInstanceOf(BudgetExceeded);
        }
      }),
    );
    expect(ok).toBe(10);
    expect(g.used()).toBe(10);
  });

  test("rejects invalid amounts", () => {
    const g = new BudgetGuard(10, 5);
    expect(() => g.reserve("a", -1)).toThrow();
    expect(() => g.reserve("a", NaN)).toThrow();
  });
});
